WHERE d.deleted = 0

    AND (d.name LIKE CONCAT('%', #{query.keyword}, '%')
         OR d.description LIKE CONCAT('%', #{query.keyword}, '%')
         OR s.name LIKE CONCAT('%', #{query.keyword}, '%'))


    AND d.stall_id = #{query.stallId}


    AND d.category = #{query.category}


    AND d.price >= #{query.minPrice}


    AND d.price <= #{query.maxPrice}
